python - <<'PY'
import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot(timeout=30);o=r.get_obs(depth=True,video='none');im=o.last['egocentric_mirrored_camera'];d=o.last_depth['egocentric_mirrored_camera'];
mask=(im[:,:,0]>140)&(im[:,:,1]>130)&(im[:,:,2]<100)&((im[:,:,0]-im[:,:,2])>70)&(d>0)
try:
 import cv2
 n,lab,st,cen=cv2.connectedComponentsWithStats(mask.astype('uint8'),8)
 for i in sorted(range(1,n),key=lambda i:st[i,cv2.CC_STAT_AREA],reverse=True)[:10]:print('comp',i,st[i].tolist(),cen[i].tolist())
except Exception as e: print(e)
E=np.array(o.meta['cameras']['egocentric_mirrored_camera']['extrinsic_cv']);K=np.array(o.meta['cameras']['egocentric_mirrored_camera']['intrinsic_cv']); ys,xs=np.where(mask)
for label,sel in [('all',np.ones(len(xs),bool))]:
 idx=np.arange(len(xs)); idx=idx[np.argsort(d[ys,xs])[::max(1,len(xs)//3000)]] if len(xs)>0 else []
 pts=[]
 for i in idx:
  u,v=xs[i],ys[i];z=d[v,u];cam=np.linalg.inv(K)@np.array([u*z,v*z,z]);pts.append((np.linalg.inv(np.vstack([E,[0,0,0,1]]))@np.r_[cam,1])[:3])
 if len(pts):print('world q',np.quantile(np.array(pts),[.05,.25,.5,.75,.95],axis=0), 'maskN',len(xs))
print('proprio',o.meta['proprio']['now'][8:16])
PY

